  "range_high": 0.03,
  "summary": [
    "Starting from a cautious 5% anchor, current polls place CDU/Greens ahead of AfD, making AfD unlikely to win the most seats.",
    "Historical patterns in Baden-Württemberg show AfD has never led the seat tally, with Greens and CDU traditionally ahead.",
    "The state's electoral system (mixed-member proportional representation with a 5% threshold) tends to consolidate seats among larger parties, further reducing AfD's top-seat prospects.",
    "A tail-risk event could lift AfD temporarily, but the baseline remains anchored near 1% with limited upside."
  ],
  "confidence": "high",
  "narrative": "Bayesian updating driven by February 2026 polls and BW's electoral dynamics yields a posterior probability of about 1% that AfD wins the most seats. Starting from a 5% anchor, multiple factors push the estimate downward; only a potential late shock could offer a modest uptick, but the calibrated result remains near 1%.",
  "justification": {
    "anchor": {
      "probability": 0.05,
      "basis": "Reference class is Baden-Württemberg state elections under MMP with a 5% threshold; historically CDU or Greens lead and AfD has not led BW. The 5% anchor reflects the cautious baseline used in the provided forecasts."
    },
    "factor_updates": [
      {
        "factor": "Polls placing CDU/Greens ahead of AfD",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "As of February 2026, CDU ~28–29%, Greens ~21–27%, AfD ~18–21%, reducing likelihood AfD leads in seat tally given distribution rules."
      },
      {
        "factor": "Historical patterns in Baden-Württemberg",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "AfD has never led BW's seat tally; Greens/CDU have historically topped the field, lowering top-seat odds for AfD."
      },
      {
        "factor": "Electoral system and 5% threshold effects",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Two-stimme system with a 5% hurdle tends to favor larger parties and complicates a scenario where AfD wins the most seats."
      },
      {
        "factor": "Tail-risk event that could boost AfD",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Unforeseen national/local issues could temporarily lift AfD's support and alter the race."
      },
      {
        "factor": "External predictions discounting AfD's top-seat win",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "AI-driven and polling forecasts broadly imply AfD is not on track to win the most seats."
      }
    ],
    "synthesis_rationale": "The posterior is anchored at 5% and is pulled downward by strong, corroborating poll data and structural factors (historical patterns, electoral rules). Tail risks exist but are insufficient to shift the calibrated probability meaningfully; the synthesis reflects a high-confidence, low-probability outcome consistent with the Bayesian update to ~1%."
  }
}

